installed_disc_needs_smp_row: "Cần ShadowMount+ đang chạy để gắn + khởi chạy.",
installed_kstuff_off_title: "kstuff chưa hoạt động — game sẽ không khởi chạy",
installed_kstuff_off_body: "Payload không có quyền đọc/ghi nhân (kernel), nghĩa là điểm vào jailbreak/kstuff chưa được nạp. Khởi chạy (và cài đặt) game fpkg sẽ thất bại cho đến khi bạn nạp máy qua kstuff và kết nối lại.",
installed_kstuff_on: "kstuff đang hoạt động (kernel R/W) — sẵn sàng cài đặt và khởi chạy.",
installed_smp_off_title: "{count} ảnh đĩa cần ShadowMount+ đang chạy",
installed_smp_off_body: "Các tựa game ảnh đĩa được gắn từ /mnt/shadowmnt bởi ShadowMount+. Có vẻ nó chưa chạy, nên các tựa đó sẽ không gắn hoặc khởi chạy được. Gửi nó tới máy, đợi vài giây, rồi Làm mới.",
installed_smp_send: "Gửi ShadowMount+",
installed_smp_not_downloaded: "ShadowMount+ chưa được tải xuống — lấy nó từ tab Payload, rồi quay lại và gửi.",
installed_smp_sent: "Đã gửi ShadowMount+ — đợi vài giây, rồi Làm mới.",
