  reset_hint: "Xóa sạch mọi dấu vết cục bộ của PS5Upload và bắt đầu lại: cài đặt, các PS5 đã lưu, lịch sử hoạt động/hàng đợi, bộ nhớ đệm payload và báo cáo sự cố. Không ảnh hưởng gì trên PS5 của bạn. Hãy xuất bản sao lưu ở trên trước nếu bạn có thể cần lại.",
