a11y_color_blind_hint: "Điều chỉnh màu trạng thái (thành công/cảnh báo/lỗi) để phân biệt được với loại thị giác màu đã chọn.",
a11y_density_hint: "Kiểm soát khoảng cách và đệm trong toàn ứng dụng. Rộng rãi dành thêm chỗ cho thao tác chạm; Gọn hiển thị được nhiều hơn trên màn hình.",
a11y_high_contrast_hint: "Tăng độ tương phản màu ngữ nghĩa cho văn bản, viền và vòng lấy nét.",
a11y_motion_hint: "Tự động theo cài đặt hệ điều hành. Giảm bớt phát chuyển cảnh ở tốc độ 0,4×; Không tắt hoàn toàn.",
a11y_sr_hints_hint: "Thêm nhãn aria chi tiết để đọc thêm ngữ cảnh (ví dụ “Làm mới kết nối” thay vì chỉ “Nút”).",
activity_preparing_hint: "Đang chuẩn bị… chưa truyền dữ liệu. Kho nén (.zip/.rar/.7z) được giải nén trên máy tính của bạn trước — với tệp lớn có thể mất một lúc trước khi hiện tốc độ tải lên.",
backup_delete_confirm_msg: "Xóa {tag} @ {ts}? Không thể hoàn tác.",
backup_restore_confirm_msg: "Khôi phục {tag} @ {ts}? Thao tác này sẽ ghi đè các tệp hiện tại.",
