backup_warning: "Bản chụp được lưu trên PS5 tại /data/ps5upload/backups/. Khôi phục sẽ ghi đè các tệp hiện có tại đường dẫn gốc.",
bringup_chain_with: "{name} → trình trợ giúp → trình tải tự động",
bringup_desc: "Một chạm: tải payload khởi tạo, gửi trình trợ giúp, rồi chờ đến khi PS5 sẵn sàng.",
bringup_failed: "Khởi tạo thất bại ở {phase}: {error}",
bringup_phase_prehelper: "Đang tải payload khởi tạo ({name})…",
cheats_description: "Áp dụng bản vá bộ nhớ cho trò chơi đang chạy. Hỗ trợ tệp JSON, SHN và tệp vá.",
cheats_search_hint: "Nhập tên trò chơi hoặc Title ID (ví dụ CUSA00001) rồi nhấn Tìm",
connection_step2_browser_unsupported: "Trình duyệt không thể đọc tệp trợ giúp cục bộ để gửi. Hãy tải trình trợ giúp từ ứng dụng máy tính hoặc từ trình tải tự động USB trước, rồi trang này sẽ tự phát hiện.",
dashboard_running_apps: "Ứng dụng đang chạy ({n})",
engine_url_hint: "Nơi ứng dụng kết nối tới ps5upload-engine. Giữ nguyên sidecar cục bộ mặc định, hoặc trỏ tới một engine từ xa/tự lưu trữ. Khởi động lại ứng dụng sau khi chuyển giữa cục bộ và từ xa.",
err_fs_read_path_not_allowed: "Tệp này nằm trong phân vùng hệ thống chỉ đọc, thường bị chặn. Bật Cài đặt → “Cho phép tải tệp hệ thống” để đọc từ /system, /system_data và các đường dẫn được bảo vệ khác. Việc này chỉ ảnh hưởng đến tải xuống — xóa, di chuyển và ghi luôn bị cấm ở đó.",
err_rar_open_failed: "Không đọc được kho RAR này. Nếu là bộ nhiều phần, hãy chọn phần ĐẦU TIÊN (…part1.rar / …part01.rar / ….rar) và đảm bảo mọi phần nằm cùng thư mục. Nếu có mật khẩu, hãy nhập mật khẩu.",
err_rar_password_required: "Kho RAR này được bảo vệ bằng mật khẩu. Nhập mật khẩu bên dưới để đọc và tải nội dung lên.",
err_rar_unsafe_entry: "Kho RAR này chứa đường dẫn tệp trỏ ra ngoài thư mục đích nên đã bị từ chối vì an toàn. Kho lưu có thể bị hỏng.",
err_rar_unsupported: "Bản dựng này không hỗ trợ kho RAR (Android chỉ tải lên .zip và .7z). Hãy giải nén .rar trên máy tính trước, hoặc dùng ứng dụng máy tính.",
fanCurve_hint: "Xác định các điểm nhiệt độ – tốc độ quạt. PS5 sẽ nội suy giữa chúng.",
fanCurve_persisted: "PS5 này đã lưu một đường cong quạt. Nhiệt độ của điểm đầu tiên là ngưỡng quạt đang áp dụng và tự khôi phục mỗi lần nạp payload — không cần ứng dụng máy tính.",
fs_download_zip_dialog_title: "Lưu “{name}” dưới dạng .zip",
fs_install_confirm_body_usb: "Thao tác này đưa gói vào bộ nhớ trong (máy không cài trực tiếp từ USB được), cài đặt, rồi xóa bản sao tạm. Tệp gốc trên ổ của bạn không bị đụng đến.",
fs_install_confirm_title: "Cài “{name}”?",
fs_install_done: "Đã cài {name}",
fs_install_may_not_launch: "Bản cài đã được ghi nhận, nhưng tựa game có thể không khởi chạy — hãy kiểm tra Ứng dụng đã cài.",
fs_op_on_other_console: "Đang có thao tác tệp chạy trên {name} — chuyển sang tab của máy đó để xem tiến độ.",
fs_path_gone_body: "{path} không còn tồn tại trên PS5.",
fs_rename_target_exists: "Ở đây đã có mục tên “{name}” — đổi tên sẽ ghi đè lên nó. Hãy chọn tên khác hoặc xóa nó trước.",
fw_spoof_kernel_unknown_warn: "Không đọc được phiên bản kernel — việc phát hiện giả mạo có thể không đáng tin.",
game_hub_launch_unconfirmed_body: "PS5 đã chấp nhận yêu cầu khởi chạy nhưng tựa game chưa xuất hiện. Hãy kiểm tra máy — có thể nó vẫn đang khởi động.",
game_hub_media_not_per_game: "PS5 không gắn thẻ ảnh chụp hay đoạn video theo trò chơi tạo ra chúng — chúng được lưu theo ngày, không theo tựa game. Hãy duyệt tất cả trên máy:",
game_hub_no_addons: "Chưa có gói DLC nào được chuẩn bị cho tựa game này. Hãy tải lên một gói từ Cài đặt gói.",
game_hub_no_updates: "Chưa có gói cập nhật nào được chuẩn bị cho tựa game này. Hãy tải lên một gói từ Cài đặt gói.",
installed_all_played: "Mọi tựa game đã cài đều từng được thấy đang chơi khi ps5upload mở — không có mục nào bị đánh dấu là không dùng.",
installed_launch_slow: "Đã gửi lệnh khởi chạy — lần đầu có thể lâu. Chờ một lát rồi kiểm tra PS5 của bạn.",
installed_playtime_line: "{time} · thấy lần cuối {seen}",
installed_playtime_tooltip: "Thời gian chơi và lần thấy cuối chỉ được ghi khi ps5upload mở và đang theo dõi — đây không phải bản ghi của chính máy.",
installed_stop_confirm_body: "Thao tác này đóng trò chơi đang chạy trên PS5. Tiến trình chưa lưu sẽ mất — giống như thoát từ máy.",
