notifications_unread: "{count} chưa đọc",
payloads_add_repo_hint: "Dán owner/name (ví dụ EchoStretch/kstuff-lite) hoặc URL kho đầy đủ. Bản phát hành được lấy giống như danh sách tuyển chọn; khi tải xuống vẫn áp dụng các kiểm tra ELF/zip như nhau. Chỉ thêm kho mà bạn tin tưởng — ps5upload không kiểm duyệt nội dung của kho tùy chỉnh.",
