about_disclaimer_title: "Tuyên bố miễn trừ trách nhiệm",
about_disclaimer_purpose: "ps5upload chỉ được cung cấp cho mục đích nghiên cứu, giáo dục, khả năng tương tác và phát triển homebrew. Phần mềm này không liên kết, không được chứng thực và không có quan hệ với Sony Interactive Entertainment Inc. “PlayStation” và “PS5” là nhãn hiệu của Sony Interactive Entertainment Inc., chỉ được dùng ở đây để nhận dạng.",
about_disclaimer_piracy: "Chỉ sử dụng với phần cứng bạn sở hữu và nội dung bạn sở hữu hợp pháp. Không được dùng để sao chép, phân phối hoặc chạy phần mềm mà bạn không có quyền sử dụng.",
about_disclaimer_risk: "Phần mềm này được cung cấp “nguyên trạng”, không kèm bảo đảm dưới bất kỳ hình thức nào. Vận hành một máy đã chỉnh sửa có thể làm hỏng máy vĩnh viễn, phá hủy không thể phục hồi các bản lưu và giấy phép, đồng thời khiến tài khoản hoặc máy của bạn bị cấm. Bạn hoàn toàn tự chịu rủi ro và chịu trách nhiệm đầy đủ về hậu quả. Hãy sao lưu mọi thứ bạn không thể để mất trước khi bắt đầu.",
about_disclaimer_read_full: "Đọc toàn bộ điều khoản",
backup_explain: "Sao chép tệp từ máy chơi game sang máy tính này để bạn có thể phục hồi lại sau. Chọn một mục thông dụng bên dưới, hoặc tự nhập đường dẫn của bạn.",
