game_activity_reset_explain: "Thao tác này xóa vĩnh viễn thời gian chơi mà ps5upload đã ghi trên máy này. Không thể hoàn tác và không thể khôi phục các phiên trước. Dữ liệu ghi nhận của chính máy bạn không bị ảnh hưởng — thao tác này chỉ xóa những gì màn hình này hiển thị.",
