localimage_eject: "Tháo",
localimage_explain: "Ảnh được mở như một ổ đĩa bình thường trên máy tính này, nên bạn có thể thêm, thay thế và xóa tệp bên trong — ví dụ các tệp vá — bằng Finder hoặc Explorer, y như một chiếc USB. Thay đổi được lưu thẳng vào tệp ảnh. ps5upload không bao giờ tự ghi vào ảnh; hệ điều hành của bạn làm việc đó. Hãy tháo ảnh ở đây khi bạn xong việc.",
