"pkglib.installAll.what": "“Cài tất cả” là gì?",
"pkglib.installAll.whatBody": "“Cài tất cả” chạy lần lượt mọi gói đã sẵn sàng: game gốc → bản cập nhật → DLC. Khi bạn có hai bản cập nhật cùng phiên bản (hoặc hai gói DLC xung đột nhau), hãy dùng ô chọn trên mỗi hàng để quyết định máy này sẽ cài gói nào — chỉ một gói cho mỗi nhóm. Bỏ chọn để loại nhóm đó ra. Nút Cài đặt trên một hàng riêng lẻ luôn chỉ cài đúng gói đó.",
