edit_session_body: "Khi phiên này còn mở, game vẫn bị ẩn khỏi màn hình chính của PS5 — ShadowMount+ không thấy ảnh đĩa ở vị trí hiện tại. Kết thúc chỉnh sửa để đưa nó về chỗ cũ.",
