"fpkg.lowSpace": "Sắp hết dung lượng: chuyển đổi có thể cần tới {need} trên ổ đầu ra, hiện còn {free}.",
"fpkg.about": "Chỉ tới một thư mục trò chơi, hoặc ảnh gắn kết .exfat hay .ffpkg. Trình chuyển đổi đọc cây thư mục, kiểm tra có đủ mọi thứ một gói khởi chạy được cần, rồi ghi một .pkg định dạng debug vào thư mục đầu ra.",
"fpkg.aboutWhere": "Việc chuyển đổi chạy trên máy đang chạy engine — máy tính này, một máy chủ Docker hoặc thiết bị Android — không phải trên máy chơi game. Không gì tới được máy chơi game cho đến khi bạn cài gói — qua luồng từ máy tính này, hoặc tải lên PS5 trước.",
"fpkg.aboutSource": "Nguồn phải là cây trò chơi đã được giải mã. Bản cài retail không thể giải nén ở đây, và mục kiểm tra bên dưới sẽ báo nếu bạn đã chọn loại đó.",
"fpkg.aboutFake": "Kết quả là một gói giả, nên máy cần nạp hỗ trợ gói giả trước khi cài: kstuff (bản có hỗ trợ gói giả PS5), a53_ppr_install_fast.elf và shadowmountplus.elf, theo thứ tự đó. Mục Cài gói cũng ghi điều tương tự cạnh nút Cài.",
"fpkg.aboutChecks": "Những gì được kiểm tra",
"fpkg.checkEboot": "Một eboot.bin ở gốc cây thư mục — mô-đun trò chơi. Nó phải là ELF thô hoặc SELF được bọc; mô-đun ký retail không thể đóng gói lại.",
"fpkg.checkParam": "sce_sys/param.json, và không có sce_sys/param.sfo — param.sfo sẽ đưa đường khởi chạy của máy sang lối PS4.",
"fpkg.checkIcons": "ID nội dung 36 ký tự, cả hai biểu tượng, và mô-đun quyền sce_sys/about/right.sprx.",
"fpkg.checkDrm": "Giá trị DRM của gói là tiêu chuẩn. Giá trị miễn phí hoặc có thể nâng cấp khiến máy khóa trò chơi; nó chỉ được ghi lại trong gói, tệp của bạn không bao giờ bị động tới.",
"payloads_essentials_title": "Nên dùng cùng ps5upload",
"payloads_essentials_body": "Nếu bạn thiết lập máy lần đầu, ba payload này đáp ứng hầu hết những gì ps5upload cần: kstuff-lite (bản vá nhân mà phần lớn homebrew dựa vào), ShadowMount+ (gắn ảnh trò chơi từ bộ nhớ) và nanoDNS (giữ máy tránh đường cập nhật của Sony). Mọi thứ khác trong danh sách là tùy chọn.",
"payloads_tab_shadowmount": "ShadowMount+",
"payloads_tab_nanodns": "nanoDNS",
"payloads_description_shadowmount": "Xem trạng thái ShadowMount+, các ảnh trò chơi đã gắn, cấu hình và chẩn đoán trên PS5 đã chọn.",
"payloads_description_nanodns": "Cấu hình payload nanoDNS, xác minh phiên bản đang chạy và áp dụng các bước chuyển cấu hình an toàn.",
"navigation_history": "Xem lịch sử",
"navigation_back": "Quay lại",
"navigation_forward": "Tiến tới",
"power_wake_setup_cta": "Thiết lập đánh thức & đăng nhập",
"power_wake_offer_hint": "ps5upload có thể thiết lập việc này giúp bạn — nó đọc những gì cần từ máy. Không phải tra cứu gì, không cần ứng dụng khác.",
"power_wake_working": "Đang thiết lập máy này…",
"power_wake_working_detail": "Đang bật Remote Play, đọc tài khoản của bạn từ máy và đăng ký. Bạn không cần làm gì.",
"power_wake_needs_awake": "Hãy bật máy để thiết lập — việc ghép nối đăng ký qua mạng nên chỉ hoạt động khi máy đang thức. Bạn chỉ cần làm một lần.",
"power_wake_ready_userselect": "Đã thiết lập đánh thức — dừng ở màn hình chọn người dùng",
"power_wake_upgrade": "Đồng thời tự động đăng nhập",
"power_wake_upgrade_hint": "Một cú nhấp — ps5upload lấy khóa từ máy.",
"power_wake_paired_with": "— {name}",
"power_wake_redo": "Thiết lập lại",
"power_wake_manual": "Nhập khóa thủ công",
"power_wake_manual_hint": "Chỉ cần khi máy này từ chối ghép nối. Điền phần nào cũng được: chỉ mã đánh thức thì máy thức tới màn hình chọn người dùng; cả hai khóa phiên sẽ đăng nhập luôn người dùng của bạn.",
"power_wake_code_label_v2": "Mã đánh thức",
"power_wake_signin_keys_label": "Khóa phiên (mỗi khóa 32 ký tự hex)",
"power_wake_req_title_v2": "Những gì cần bật trên máy",
"power_telemetry_note_unsupported_firmware": "Firmware của máy này không cung cấp bộ đếm sức khỏe ICC, nên không có gì để đọc. Máy và ps5upload đều không có vấn đề gì.",
"power_telemetry_note_calls_failed": "Máy cung cấp các bộ đếm này nhưng từ chối đọc. Thường sẽ hết sau khi khởi động lại.",
"power_telemetry_note_partial": "Máy này chỉ báo một số bộ đếm. Các dòng trống không phải lỗi — firmware của máy không cung cấp chúng.",
"settings_group_beta": "Tính năng beta",
"settings_card_beta": "Tính năng beta",
"beta_features_label": "Hiện các tính năng còn đang hoàn thiện",
"beta_features_hint": "Thêm vào thanh bên các màn hình đang phát triển. Chúng dùng được nhưng chưa ổn định, và có thể thay đổi hoặc bị gỡ. Hiện tại tùy chọn này hiện trình tạo FPKG (Chuyển sang FPKG).",
"bug_report_open_github": "Mở issue trên GitHub",
"bug_report_post_hint_v2": "Giờ hãy gửi nó tới nơi sẽ có người xem: mở một issue trên GitHub và đính kèm tệp .zip, hoặc đăng vào kênh báo lỗi trên Discord. GitHub tốt hơn cho mọi thứ cần theo dõi tới khi sửa; Discord nhanh hơn nếu bạn chỉ muốn hỏi đó có phải lỗi đã biết không. Dù cách nào, hãy mô tả ngắn gọn bạn đang làm gì.",
"profile.accountId.label": "ID tài khoản",
"profile.accountId.change": "Thay đổi",
"profile.accountId.apply": "Áp dụng",
"profile.accountId.invalid": "Nhập 1–16 chữ số hex (khác không).",
"profile.accountId.confirm_title": "Đổi ID tài khoản?",
"profile.accountId.confirm_replace": "Khe {slot} đã có ID tài khoản {old}.\n\nĐổi sang {next} nghĩa là các bản lưu tạo dưới {old} sẽ không còn được nhận là thuộc hồ sơ này. Chúng không bị xóa — đặt lại {old} sẽ khôi phục quyền truy cập.\n\nHãy ghi lại trước khi tiếp tục. Đổi ID tài khoản?",
"profile.accountId.confirm_set": "Đặt ID tài khoản của khe {slot} thành {next}?\n\nViệc này kích hoạt tài khoản ngoại tuyến. Các bản lưu tạo từ giờ gắn với ID này — nếu sau này bạn đổi, chúng sẽ không được nhận ra cho tới khi bạn đặt lại.",
"pkglib.url.title": "Cài từ liên kết HTTP(S)",
"pkglib.url.help": "Máy tính này tải gói qua nhiều kết nối cùng lúc và chuyển tiếp tới PS5 trong mạng của bạn, nên tốc độ truyền bằng tốc độ đường truyền của bạn thay vì luồng đơn chậm hơn của máy chơi game. Không lưu gì trên cả hai máy, nên trò chơi 100 GB không cần dung lượng trống. Liên kết phải là tải xuống trực tiếp có hỗ trợ dải byte. Giữ máy tính này thức cho tới khi cài xong.",
"pkglib.url.label": "URL gói trực tiếp",
"pkglib.url.install": "Cài liên kết",
"pkglib.url.confirmTitle": "Bắt đầu cài từ liên kết (thử nghiệm)?",
"pkglib.url.confirmBody": "Máy tính này tải gói từ liên kết và chuyển tiếp tới PS5, nên phải luôn thức và kết nối cho tới khi cài xong. Cài lại đè lên một trò chơi đã có có thể xóa nó nếu trình cài của Sony thất bại. Chỉ dùng URL gói đáng tin mà bạn được phép cài.",
"pkglib.url.confirm": "Bắt đầu cài",
