"pkg_storage_fallback_title": "Đang dùng bộ nhớ trong",
"pkg_storage_fallback_body": "Ổ lưu gói mặc định ({drive}) không khả dụng, nên gói này được lưu vào bộ nhớ trong.",
"pkglib.meta.drive": "trên {drive}",
"library_mount_modal_rw_title": "Đọc-ghi — bạn có thể sửa ảnh này",
"library_mount_modal_rw_body": "Gắn theo cách này, bạn có thể thay tệp, thêm DLC hoặc áp dụng bản vá backport — dùng Trình duyệt tệp để sửa bản gắn. Thay đổi được ghi thẳng vào tệp ảnh: sửa sai có thể khiến trò chơi không khởi động được và không hoàn tác được, nên hãy sao chép ảnh trước nếu nó quan trọng. PS5 cũng có thể tự ghi dữ liệu lưu vào ảnh đang gắn.",
"fs_add_files": "Thêm tệp",
"fs_add_files_dialog_title": "Chọn tệp để sao chép lên PS5",
"fs_replace": "Thay tệp",
"fs_replace_tooltip": "Ghi đè tệp này bằng một tệp từ máy tính của bạn — đây là cách vá một tệp bên trong ảnh trò chơi đang gắn",
"fs_replace_dialog_title": "Chọn tệp để thay “{name}”",
"fs_replace_confirm_title": "Thay tệp này?",
"fs_replace_confirm_body": "“{name}” sẽ bị ghi đè và nội dung cũ mất vĩnh viễn. Nếu tệp nằm trong ảnh trò chơi đang gắn, tệp sai có thể khiến trò chơi không khởi động.",
"fs_replace_confirm_ok": "Thay",
"fs_busy_uploading": "Đang sao chép lên PS5",
"notif_fs_upload_failed": "Sao chép lên PS5 thất bại",
"volumes_mounted_rw": "đọc-ghi",
"pkg.patch_loader_not_listening": "Không áp dụng được bản cập nhật này vì trình nạp payload của PS5 đang chạy nhưng không nhận kết nối trên cổng 9021, nên trình cài cần thiết chưa bao giờ được gửi tới và máy chưa từng thấy bản cập nhật. Trò chơi gốc vẫn nguyên vẹn. Hãy nạp lại từ trang jailbreak của bạn — một tiến trình trình nạp đã phục vụ một payload không phải lúc nào cũng tiếp tục lắng nghe. Bản cập nhật đã có trên PS5, nên không cần tải lên lại — hãy thử cài lại từ danh sách Gói. Bạn cũng có thể áp dụng bản cập nhật ngay trên PS5: Cài đặt → Hệ thống → Cài đặt gỡ lỗi → Trò chơi → Package Installer.",
"pkg.reverify_impossible": "PS5 đã nhận lần cài này, nhưng ps5upload không có gì để nhận diện gói đã cài nên không thể xác nhận. Hãy xem kết quả trong Thông báo của PS5. Gói đã chuẩn bị vẫn được giữ lại.",
"pkg.reverify_gave_up": "Vẫn chưa xác nhận sau 30 phút. Trò chơi rất lớn có thể mất lâu hơn — hãy xem Thông báo của PS5, hoặc dùng Kiểm tra lại.",
"backport_action": "Backport",
"backport_auto": "Tự động thử các bộ",
"backport_auto_hint": "Cài một bộ, khởi chạy trò chơi, và nếu không chạy được thì hoàn tác rồi chuyển sang bộ tiếp theo — cho tới khi một bộ chạy được hoặc hết bộ.",
"backport_auto_running": "Đang thử {label} — bộ {index}/{total}…",
"backport_auto_stop": "Dừng",
