"backport_overlay_missing": "Hãy gửi payload ps5upload hiện tại trước khi áp dụng backport. Payload cũ không gắn được các thư viện đã chọn khi trò chơi khởi chạy.",
"backport_failed": "Không hoàn tất được backport",
"backport_inspecting": "Đang kiểm tra các họ thư viện đã cài…",
"backport_summary": "Việc này hạ trò chơi xuống cặp SDK của FW 4 và cài bộ {count} thư viện đi kèm {set}. Một bộ được cài trọn vẹn — trộn thư viện giữa các trò chơi chính là lý do backport không khởi chạy được.",
"settings_card_fakelibs": "Thư viện backport",
"backport_verify_unpatched": "Trò chơi này chưa được backport",
"backport_verify_unpatched_body": "eboot của nó vẫn mang phiên bản SDK gốc, nên không thể chạy trên firmware này dù cài thư viện nào — bộ thư viện không phải là vấn đề. Hãy chạy lại backport; nếu vẫn xảy ra, bản vá SDK không được áp dụng.",
"backport_no_larger": "Trò chơi này cần những thư viện mà không bộ nào của bạn có. Hãy nhập một gói đầy đủ hơn, hoặc quét một máy khác.",
"backport_verifying": "Đang khởi chạy và theo dõi — lần khởi chạy lỗi sẽ được thử lại, vì khởi chạy kém ổn định tới mức một lần lỗi không chứng minh được gì.",
