ps5src_need_two: "Thêm máy thứ hai vào danh sách để sao chép giữa các máy.",
ps5src_hint: "Sao chép tệp hoặc thư mục từ máy khác sang máy này qua mạng của bạn. Dữ liệu đi qua máy tính này; không có gì được lưu lại trên đó.",
ps5src_from_console: "Máy nguồn",
ps5src_from_path: "Đường dẫn trên máy nguồn",
ps5src_dest_path: "Đường dẫn đích trên máy này",
ps5src_start: "Sao chép sang PS5 này",
ps5src_need_source_path: "Nhập đường dẫn nguồn, bắt đầu bằng /",
ps5src_need_dest_path: "Nhập đường dẫn đích, bắt đầu bằng /",
queue_rar_password_required: "Tệp lưu trữ này cần mật khẩu.",
queue_rar_password_wrong: "Mật khẩu đó sai. Hãy thử lại.",
queue_rar_password_retry: "Thử lại với mật khẩu",
err_replace_in_progress: "Trình trợ giúp trên máy này đang được thay thế. Hãy đợi hoàn tất rồi thử lại.",
err_replace_cooldown: "Trình trợ giúp trên máy này vừa được thay thế. Hãy đợi một phút trước khi thay thế lại.",
"joberr.ava1_refused": "PS5 đã từ chối yêu cầu này (mã {code}). Hãy thử lại; nếu lặp lại, hãy cập nhật trình trợ giúp và ứng dụng lên cùng phiên bản và đính kèm mã này vào báo cáo lỗi.",
"joberr.ava1_busy": "Trình trợ giúp PS5 đang bận và không kịp nhận lần truyền này. Hãy đợi nó xong việc khác rồi nhấp Thử lại.",
"joberr.ava1_unreachable": "Không thể kết nối tới PS5. Hãy kiểm tra máy đang bật, cùng mạng và trình trợ giúp đang chạy, rồi nhấp Thử lại.",
"joberr.ava1_exists": "Đích đã tồn tại trên PS5. Chọn Ghi đè để thay thế, hoặc chọn đích khác.",
"joberr.ava1_commit_exists": "Tệp đã được tải lên nhưng không thể xuất bản vì đích đã tồn tại. Chọn Ghi đè để thay thế, hoặc chọn đích khác.",
"joberr.ava1_cross_device": "Đích nằm trên ổ khác với vùng tạm nên PS5 không thể di chuyển tệp. Hãy chọn đích trên cùng ổ hoặc tải lên ổ trong trước.",
"joberr.ava1_wrong_console": "Thiết bị tại địa chỉ này không phải PS5 đã ghép đôi với ứng dụng. Hãy kiểm tra địa chỉ hoặc ghép đôi lại với máy này.",
"joberr.ava1_no_identity": "Ứng dụng này chưa có danh tính ghép đôi. Hãy ghép đôi với PS5 ở màn hình Kết nối rồi thử lại.",
"joberr.zip_read_error": "Không đọc được tệp .zip (tệp hoặc ổ chứa nó có thể đã biến mất giữa chừng). Hãy kiểm tra nguồn vẫn đang kết nối rồi nhấp Thử lại.",
"joberr.ava1_zip_corrupt": "Không đọc được tệp .zip này: nó bị hỏng hoặc không đầy đủ. Hãy tải lại hoặc tạo lại rồi thử lại.",
"joberr.ava1_7z_corrupt": "Không đọc được tệp .7z này: nó bị hỏng hoặc không đầy đủ. Hãy tải lại hoặc tạo lại rồi thử lại.",
"joberr.ava1_7z_encrypted": "Tệp .7z này được mã hóa nên không thể truyền trực tiếp. Hãy giải nén trên máy tính và tải thư mục lên thay thế.",
"joberr.ava1_7z_unsafe_path": "Tệp .7z này chứa đường dẫn không an toàn (thoát ra ngoài thư mục của nó). Hãy giải nén trên máy tính và tải thư mục lên thay thế.",
"joberr.rar_password": "Tệp .rar này cần mật khẩu, hoặc mật khẩu đã nhập sai. Hãy nhập đúng mật khẩu rồi thử lại.",
"joberr.rar_corrupt": "Tệp .rar này bị hỏng, hoặc thiếu một số phần hay sai thứ tự. Hãy đảm bảo đủ mọi phần rồi thử lại.",
"joberr.ava1_copy_lost": "PS5 đã mất dấu lần sao chép này (trình trợ giúp khởi động lại hoặc mất kết nối). Nhấp Thử lại để bắt đầu lại.",
"joberr.ava1_copy_failed": "PS5 không thể hoàn tất việc sao chép. Hãy kiểm tra dung lượng trống và nguồn cùng đích còn khả dụng, rồi thử lại.",
"joberr.ava1_local_io": "Máy tính này không thể ghi tệp đã tải xuống. Hãy kiểm tra quyền và dung lượng trống của thư mục đích rồi thử lại.",
"joberr.ava1_bad_manifest": "PS5 gửi danh sách tệp mà ứng dụng này không hiểu. Hãy cập nhật trình trợ giúp và ứng dụng lên cùng phiên bản rồi thử lại.",
"joberr.helper_not_ava1": "Trình trợ giúp PS5 không chạy. Hãy gửi nó từ màn hình Kết nối (hoặc dùng Cập nhật trình trợ giúp nếu biểu ngữ đề xuất) rồi thử lại.",
"joberr.helper_not_ava1_web": "Trình trợ giúp PS5 không chạy. Giao diện web này không thể gửi nó: hãy khởi chạy payload ps5upload trên máy bằng trình nạp payload quen dùng của bạn (hoặc dùng Cập nhật trình trợ giúp nếu biểu ngữ đề xuất) rồi thử lại.",
"joberr.helper_old": "PS5 đang chạy trình trợ giúp cũ hơn. Hãy nhấp Cập nhật trình trợ giúp ở biểu ngữ phía trên rồi thử lại.",
"joberr.not_paired": "PS5 này chưa chấp nhận ứng dụng này. Hãy ghép đôi chúng (nút Ghép đôi…) rồi thử lại.",
"joberr.helper_starting": "Trình trợ giúp PS5 vẫn đang khởi động. Hãy đợi vài giây rồi thử lại.",
"joberr.ava1_failed": "Trình trợ giúp PS5 đã khởi động nhưng máy chủ truyền của nó thì không. Hãy khởi động lại máy rồi thử lại.",
"joberr.helper_not_running": "Không có trình trợ giúp nào đang chạy trên PS5. Hãy gửi trình trợ giúp trước (màn hình Kết nối của ứng dụng máy tính hoặc trình nạp payload của bạn) rồi thử lại.",
