installed_launch_smp_refused: "PS5 từ chối khởi động trò chơi này (0x80940033) dù kstuff đang chạy. ShadowMount+ gắn trò chơi khi nó khởi động, và việc đó đã không xảy ra. Hãy đóng trò chơi đang chạy, gửi lại ShadowMount+ từ Payloads rồi nhấn Chơi.",
