remotePlay_np_title: "Bật cài đặt Remote Play của chính PS5",
remotePlay_np_body: "PS5 chỉ cho bật Remote Play với tài khoản đã đăng nhập PlayStation Network. np-fake-signin {version} khiến máy coi tài khoản của bạn là đã đăng nhập mà không cần đăng nhập PSN thật. Sau khi chạy, có thể bật công tắc trong Settings → System → Remote Play.",
