kept_open: "Mở trong Tệp",
kept_clean_title: "Xóa các tệp này khỏi PS5?",
kept_clean_body: "Mọi thứ trong {path} ({size}) sẽ bị xóa. Đây là phần còn sót mà ps5upload có thể tạo lại; thư viện gói và bản sao lưu save của bạn không bị đụng tới.",
library_move_retry: "Thử di chuyển lại",
volumes_pkg_copies_here: "Bản sao gói được lưu ở đây",
volumes_store_pkg_copies: "Lưu bản sao gói ở đây",
volumes_pkg_copies_hint: "Lựa chọn này làm gì: “Tải lên & cài đặt” trước hết sao chép tệp .pkg lên PS5, rồi cài từ bản sao đó. Ở đây chỉ chọn ổ nào giữ các bản sao ấy. Nó không thay đổi nơi cài game (PS5 quyết định trong phần cài đặt Lưu trữ của máy), và “Truyền & cài đặt” không giữ bản sao nào. Nếu ổ đã chọn không được kết nối, bản sao sẽ vào bộ nhớ trong.",
saves_auto_folder_label: "Thư mục sao lưu",
captures: "Ảnh chụp & clip",
captures_title: "Bản ghi",
"arcpkg.choose": "Chọn tệp nén…",
"arcpkg.help": "Dành cho tệp .zip, .7z hoặc .rar chứa một hay nhiều tệp .pkg trong bất kỳ thư mục nào. Chỉ các gói được giải nén, thẳng lên PS5 (không có gì được giải nén trên máy tính này), rồi được cài lần lượt: game gốc trước, sau đó là bản cập nhật, rồi DLC. Hỗ trợ RAR nhiều phần (.part1.rar, .part2.rar…): chọn phần đầu tiên và để các phần còn lại bên cạnh. Mật khẩu sẽ được hỏi khi RAR cần; ZIP và 7z có mật khẩu không được hỗ trợ.",
"arcpkg.keepsRunning": "Việc này vẫn tiếp tục nếu bạn mở màn hình khác, và cũng hiển thị trong Tác vụ.",
"arcpkg.notArchive": "Tệp đó không phải là tệp nén .zip, .7z hoặc .rar.",
"arcpkg.pick": "Chọn một tệp nén",
"arcpkg.title": "Cài gói từ tệp nén",
"install.library.title": "Bản sao gói trên PS5",
"install.stream.file.help": "Chọn tệp .pkg hoặc .fpkg, hoặc thả vào bất kỳ đâu trên cửa sổ này. Hãy để ứng dụng mở cho đến khi cài xong; tiến trình hiển thị trong hàng đợi ở trên và trong Tác vụ.",
"install.stream.file.title": "Cài một tệp gói",
"install.tab.stream.lead": "PS5 cài thẳng từ máy tính này hoặc từ một liên kết. Không có bản sao nào được đặt lên PS5 trước, nên không cần dung lượng trống ở đó, và đây là cách cài đáng tin cậy nhất.",
"install.tab.upload.lead": "Gói được sao chép lên PS5 trước, rồi cài từ bản sao đó. Dùng cách này khi PS5 không kết nối được tới máy tính này (truyền trực tiếp thất bại do lỗi mạng), hoặc để giữ gói trên PS5 và cài lại sau mà không cần máy tính này.",
"install.upload.file.browser": "Sao chép gói lên PS5 từ đây cần ứng dụng máy tính. Trên giao diện web, hãy dùng Truyền và cài đặt, hoặc cài các gói đã có trên PS5 ở bên dưới.",
"install.upload.file.help": "Chọn tệp .pkg hoặc .fpkg. Bản sao cần dung lượng trống trên PS5 bằng cả gói, và nằm trong danh sách bên dưới cho đến khi bạn xóa nó.",
"install.upload.file.title": "Sao chép gói lên PS5 và cài đặt",
"linkcard.confirm.direct": "PS5 tự tải gói từ liên kết và cài đặt. Sau khi bắt đầu thì không cần máy tính này nữa, và tiến trình hiển thị trên PS5 (Tải về), không phải ở đây. Nếu PS5 không truy cập được liên kết, ứng dụng sẽ chuyển tiếp qua máy tính này. Cài đè lên game đã cài có thể xóa game đó nếu trình cài đặt của Sony thất bại. Chỉ dùng liên kết tới các gói mà bạn tin tưởng và có quyền cài.",
"linkcard.confirm.download": "Máy tính này lưu toàn bộ gói vào đĩa trước, rồi cài lên PS5. Máy phải bật cho đến khi cả hai bước xong, và cần dung lượng trống cho gói. Cài đè lên game đã cài có thể xóa game đó nếu trình cài đặt của Sony thất bại. Chỉ dùng liên kết tới các gói mà bạn tin tưởng và có quyền cài.",
"linkcard.confirm.stream": "Máy tính này tải gói và chuyển thẳng cho PS5, nên phải bật và giữ kết nối cho đến khi cài xong. Không có gì được lưu vào đĩa. Cài đè lên game đã cài có thể xóa game đó nếu trình cài đặt của Sony thất bại. Chỉ dùng liên kết tới các gói mà bạn tin tưởng và có quyền cài.",
"linkcard.confirm.title": "Cài từ liên kết này?",
"linkcard.fact.awake": "Đừng để máy tính này ngủ",
"linkcard.fact.can_close": "Bạn có thể đóng ứng dụng",
"linkcard.fact.disk": "Cần dung lượng đĩa ở đây",
"linkcard.fact.no_disk": "Không cần dung lượng đĩa",
"linkcard.fact.progress_here": "Tiến trình hiển thị ở đây",
"linkcard.fact.progress_ps5": "Tiến trình hiển thị trên PS5",
"linkcard.forget": "Xóa khỏi danh sách",
"linkcard.help": "Dán liên kết trực tiếp tới một tệp .pkg. Không có gì được sao chép lên PS5 trước, nên game 100 GB không cần thêm dung lượng ở đó.",
"linkcard.how": "Lấy gói bằng cách nào?",
"linkcard.insecure": "Bỏ qua kiểm tra chứng chỉ",
"linkcard.insecure_hint": "Dành cho máy chủ của riêng bạn hoặc trang có chứng chỉ đã hết hạn. Có hiệu lực ở đây vì máy tính này là bên tạo kết nối.",
"linkcard.install": "Cài từ liên kết",
"linkcard.mode.direct": "Để PS5 tự tải",
"linkcard.mode.direct_body": "PS5 tự lấy liên kết. PS5 phải truy cập được liên kết và địa chỉ phải ngắn (địa chỉ dài sẽ được ứng dụng rút gọn, và khi đó ứng dụng phải luôn mở).",
"linkcard.mode.download": "Tải về đây trước, rồi cài",
"linkcard.mode.download_body": "Máy tính này lưu toàn bộ gói, rồi cài đặt. Đây là cách chậm nhất, nhưng nếu liên kết hết hạn hoặc bị ngắt, bạn chỉ cần thử tải lại.",
"linkcard.mode.stream": "Truyền qua máy tính này",
"linkcard.mode.stream_body": "Máy tính này tải bằng nhiều kết nối và chuyển thẳng cho PS5. Thường là nhanh nhất, và hoạt động cả khi chỉ máy tính này truy cập được liên kết.",
"linkcard.name": "Tên (không bắt buộc)",
