"install.description.v2": "Cài các gói .pkg và .fpkg lên PS5: thẳng từ máy tính này hoặc từ liên kết (Truyền và cài đặt), hoặc từ bản sao được đặt lên PS5 trước (Tải lên và cài đặt).",
faq_collapse_all: "Đóng tất cả",
