faq_topics: "Chủ đề",
health_junk_explain_v2: "Những thứ do ps5upload tạo ra và không còn cần nữa: tệp dang dở từ các lần truyền bị gián đoạn, bản sao gói nằm trong thư mục tạm hơn một giờ, và tệp kiểm tra tốc độ cũ. Chỉ các thư mục riêng của ps5upload được xem xét; game, gói và dữ liệu lưu của bạn không bao giờ bị đụng tới.",
home_health_checking: "Đang kiểm tra mọi thứ có hoạt động không…",
