"speedtest.help": "Gửi một tệp thử tới PS5 và đọc lại theo đúng cách một lần sao chép thật diễn ra, rồi xóa nó ở cả hai phía. Việc này đo mạng của bạn giữa máy tính này và PS5, không phải internet.",
